import math


def knn_predict(train_X, train_y, x, k):
    if k < 1 or not train_X:
        raise ValueError("need k >= 1 and some training points")
    ranked = sorted(range(len(train_X)), key=lambda i: (math.dist(train_X[i], x), i))   # nearest first, earlier point first on a tie
    neighbours = ranked[:k]
    votes = {}
    nearest_rank = {}
    for rank, i in enumerate(neighbours):
        label = train_y[i]
        votes[label] = votes.get(label, 0) + 1
        nearest_rank.setdefault(label, rank)             # the first time we see a label is its nearest neighbour
    return min(votes, key=lambda label: (-votes[label], nearest_rank[label]))
